WITH latest AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct FROM promotions QUALIFY RANK() OVER (PARTITION BY channel, promo_code ORDER BY discount_pct DESC) = 1) SELECT DATE_TRUNC('WEEK', ends_on) AS week_start, COUNT(DISTINCT channel) AS distinct_channels, COUNT(*) AS num_rows, GROUPING_ID() AS grouping_level FROM latest GROUP BY ROLLUP (DATE_TRUNC('WEEK', ends_on)) ORDER BY num_rows DESC NULLS LAST;
